func (f BuilderFunc) Build(next Server) (Server, error) {
	return f(next)
}

// Build stacks the given middlewares on top of `sink`. Each builder wraps
// the result of the previous one, so the last builder given handles the
// request first:
//
//	Build(sink, core.Build(), log.Build())
//	// log -> core -> sink
//
// It stops at the first builder that fails, reporting it by its type.
func Build(sink Server, mws ...Builder) (Server, error) {
	s := sink
	for _, mw := range mws {
		v, err := mw.Build(s)
		if err != nil {
			return nil, fmt.Errorf("%T: %w", mw, err)
		}

		s = v
	}

	return s, nil
}
